head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.gIsurCd;
scwin.vScrenID = "ULDSTF20602.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    chb_Grp_All.setValue(1);
    scwin.fn_allCheck();

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_list_sync = function() {
    var secuGrpId = "";
    if ($c.stf.getObjectValue(chb_Grp_St) == 'Y') secuGrpId += '1,';
    if ($c.stf.getObjectValue(chb_Grp_Mf) == 'Y') secuGrpId += '2,';
    if ($c.stf.getObjectValue(chb_Grp_Rt) == 'Y') secuGrpId += '4,';
    if ($c.stf.getObjectValue(chb_Grp_Sc) == 'Y') secuGrpId += '6,';
    if ($c.stf.getObjectValue(chb_Grp_All) == ' Y') secuGrpId = '1,2,4,6';
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_INDUSTRY_CHG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.ind.change.condition" + "&{P}param01=" + vMarketTpCd + // 시장구분
        "&{P}param02=" + vMarketTpCd + // 시장구분
        "&{P}param03=" + secuGrpId + // 회사구분
        "&{P}param04=" + secuGrpId + // 회사구분
        "&{P}param05=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
        "&{P}param06=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
        "&{P}param07=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param08=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param09=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&{P}param10=" + $c.stf.getObjectValue(edt_EDate); // 종료일자

    dts_List_1.DataID = encodeURI(url);
    dts_List_1.reset();
    $c.cm.ShowWin(grd_List_1);
};



//그리드 더블클릭시 	
scwin.fn_ReadDetail = function(row, colid) {
    var vIsurCd = dts_List_1.getCellData(row, 'ISUR_CD');
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_INDUSTRY_CHG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.ind.change.conditionn" + "&{P}param01=" + vIsurCd;
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_List_1.getCellData(eval(obj), "ISUR_CD");
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    $c.data.downloadGridViewExcel(grd_List_1, "업종변경내역", "", "8");
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_1);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_2);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnClick = function(row, colid) {
    scwin.fn_ReadDetail(row, colid);
};
scwin.grd_List_1_OnKeyUp = function(row, colid, data) {
    scwin.fn_ReadDetail(row, colid);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅	
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.chb_Grp_All_onclick = function() {
    scwin.fn_allCheck();
};
scwin.chb_Grp_St_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Mf_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Rt_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.chb_Grp_Sc_onclick = function() {
    chb_Grp_All.setValue(0);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List_1, "TR_MKT_NM", "Show", false);
    }
    if (js_market == "2") {
        $c.stf.showObj(panel_CO_ATTR_KSE, false);
    }
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    scwin.fn_SetCode();
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
